def log(event, detail, actor='system'):
    STATE['logs'].insert(0, {
        'time': datetime.utcnow().strftime('%Y-%m-%d %H:%M:%S UTC'),
        'actor': actor,
        'event': event,
        'detail': detail,
    })


def notify(level, title, message):
    STATE['notifications'].insert(0, {
        'time': datetime.utcnow().strftime('%Y-%m-%d %H:%M:%S UTC'),
